// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        amount = bound(amount, 1, 1 ether);

        // fund the contract through its payable fallback
        vm.deal(address(this), amount);
        (bool okTop, ) = address(c).call{value: amount}("");
        assertTrue(okTop);
        assertEq(address(c).balance, amount);

        uint256 ownerBefore = address(this).balance;
        uint256 contractBefore = address(c).balance;

        // owner (the test contract) withdraws exactly `amount`
        c.withdraw(amount);

        // General rule: a successful withdraw(v) moves exactly v wei to msg.sender.
        assertTrue(
            address(this).balance == ownerBefore + amount &&
            address(c).balance == contractBefore - amount,
            "withdraw must transfer exactly _value"
        );
    }

    receive() external payable {}
}
